"""Emit LaTeX table snippet for sample counts (supplement)."""

import pandas as pd

import _bootstrap  # noqa: F401
from _bootstrap import RESULTS_ROOT

from scripts.compute_dataset_stats import main as compute_main


def csv_to_tex():
    csv_path = RESULTS_ROOT / "tables" / "sample_counts.csv"
    if not csv_path.exists():
        compute_main()
    df = pd.read_csv(csv_path)
    lines = [
        "% auto-generated by scripts/emit_sample_counts_tex.py",
        "\\begin{table}[t]",
        "\\centering",
        "\\caption{Per-domain split sizes and absolute 5\\% calibration counts "
        "(seed 42, stratified with per-class floor).}",
        "\\label{tab:sample-counts}",
        "\\scriptsize",
        "\\begin{tabular}{llrrrr}",
        "\\toprule",
        "Dataset & Domain & Train & Val & Test & Calib@5\\%\\\\",
        "\\midrule",
    ]
    for dataset in df["dataset"].unique():
        sub = df[df["dataset"] == dataset]
        for domain in sub["domain"].unique():
            dsub = sub[sub["domain"] == domain]
            row = {r["split"]: r["n"] for _, r in dsub.iterrows()}
            lines.append(
                f"{dataset.upper()} & {domain} & "
                f"{int(row.get('train', 0))} & "
                f"{int(row.get('val', 0) if 'val' in row else 0)} & "
                f"{int(row.get('test', 0))} & "
                f"{int(row.get('calib_5pct', 0))}\\\\"
            )
    lines += ["\\bottomrule", "\\end{tabular}", "\\end{table}", ""]
    out = RESULTS_ROOT / "tables" / "sample_counts_supplement.tex"
    out.write_text("\n".join(lines))
    print(f"Wrote {out}")


if __name__ == "__main__":
    csv_to_tex()
